import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Depthwise 2D convolution with vertical asymmetric kernel (K x 1), groups = C.
// Cooperative tiled implementation: each block handles a 2D output tile
// (TH x TW) for CcPerBlock channels of one batch element. Both the vertical
// filter chunk and the corresponding haloed input tile are staged in dynamic
// shared memory via CuTe tensors, so input rows shared by vertically
// adjacent outputs are fetched from global memory only once per block.
template <typename T, int TH>
__global__ void dwconv2d_k1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout,
    int InCols, int InRowsChunk)
{
  constexpr int Threads    = 128;
  constexpr int TW         = 64;
  constexpr int CcPerBlock = 4;
  constexpr int KC         = 16;
  constexpr int JPerThread = TH / 2;
  const int tid = threadIdx.x;
  // Block coordinates
